function timepicker(){if($('input[name="time"]').length){$('input[name="time"]').ptTimeSelect()}}
function tooltip(){if($('.tool_tip').length){$('.tool_tip').tooltip()};$}
function projectMasonaryLayout(){if($('.filter-layout').length){$('.filter-layout').isotope({itemSelector:'.filter-item',layoutMode:'masonry'})}
if($('.post-filter').length){$('.post-filter li').on('click',function(e){e.preventDefault();var $this=$(this);var selector=$this.attr('data-filter');$('.post-filter li').removeClass('active');$this.addClass('active');$('.filter-layout').isotope({filter:selector})})}
if($('.post-filter.has-dynamic-filters-counter').length){$('.post-filter.has-dynamic-filters-counter li').each(function(){var $this=$(this);var filterElement=$this.attr('data-filter');var count=0;if(filterElement==='*'||filterElement===''||filterElement===undefined){count=$('.filter-layout').find('.filter-item').length}else{count=$('.filter-layout').find(filterElement).length}
$this.find('.count').remove();$this.find('.filter-text').append('<span class="count">'+count+'</span>')})}}
