if($(".consultation-form").length){$(".consultation-form").each(function(){$(this).validate({submitHandler:function(form){var $form=$(form);var form_btn=$form.find('button[type="submit"]');var form_result_div=$form.find('.form-result-msg');if(!form_result_div.length){form_btn.before('<div class="form-result-msg alert alert-success" role="alert" style="display: none; margin-bottom: 15px;"></div>');form_result_div=$form.find('.form-result-msg')}
var form_btn_old_msg=form_btn.html();var loading_text=form_btn.data("loading-text")||"Please wait...";form_btn.prop('disabled',!0).html(loading_text);$form.ajaxSubmit({dataType:'json',success:function(data){if(data.status===!0){form.reset();$form.find('select').val('').trigger('change')}
form_btn.prop('disabled',!1).html(form_btn_old_msg);form_result_div.removeClass('alert-danger alert-success').addClass(data.status===!0?'alert-success':'alert-danger').html(data.message).fadeIn('slow');setTimeout(function(){form_result_div.fadeOut('slow')},6000)},error:function(xhr){form_btn.prop('disabled',!1).html(form_btn_old_msg);var message="Something went wrong. Please try again.";if(xhr.responseJSON&&xhr.responseJSON.message){message=xhr.responseJSON.message}
form_result_div.removeClass('alert-success').addClass('alert-danger').html(message).fadeIn('slow');setTimeout(function(){form_result_div.fadeOut('slow')},6000)}})}})})}
